// a topic or group page in another language: its description and intro from the table, in that language
// round 61: an entry may add its own description forms (4th) and intro (5th), and every entry may use {y1} (the data's
// last year) and the research file's values the page is given (extra: {euroclear} {euCbr} ... on the frozen-assets page)
// round 58: a title may list forms (the first that fits is used), and the title and heading may hold the page's own
// values: {armedList} with the value nArmed (the countries whose research names the kinds of supplies they sent)
export function topicCopyLang(l, e, { n, top, topV, measure, unitKey, dataTo, sumUa, sumNetPct, net = 0, isGroup, armedList = "", nArmed = 0, y1 = "", extra = {} }) {
  const [label, title, h1, desc, intro] = (TOPIC_T[e.slug] || {})[l] || [e.label, e.label, e.label];
  // round 61: the first figure without a "+" in a description (the table keeps its signs)
  const v = { ...extra, label, n, measure, unit: s(l, "unit")[unitKey], dataTo, t1: top[0] || "", topV: String(topV || "").replace(/^\+/, ""), tops: list3(l, top.slice(0, 3)), sumUa, sumNetPct, armedList, y1 }, T = C(l, ["topic"]);
  const own = { nArmed };
  // a form that needs a value this page is not given (a research file's amount) is left out
  const tryAll = (xs, nums) => (Array.isArray(xs) ? xs : [xs]).flatMap(x => { try { return [fmt(x, v, nums)]; } catch { return []; } });
  const d = desc ? tryAll(desc) : [];
  const dd = d.length ? d : fmtAll(T.description, v);
  const h = tryAll(h1, own), it = intro ? tryAll(intro) : [];
  return { label, title: fitTitle([...tryAll(title, own), label]), description: fitDesc(d.length || v.t1 ? dd : dd.slice(1)), h1: h[0] || label,
    intro: it[0] || fmt(isGroup ? T.introGroup : T.introTopic, v, { net }) };
}

// ----- country pages, every language and chance level. cat: u_sure, u_trade (English: where people search for its
// trade far more than for its aid), r_sure, u_lean or r_lean, unc, zero, party, nodata. v: the values (see COPY above),
// every word about the chance and the direction the map's own -----
export function countryText(l, cat, v, nums) {
  const T = C(l, ["country"]), key = cat === "u_lean" || cat === "r_lean" ? "lean" : cat === "u_trade" && !T.u_trade ? "u_sure" : cat;
  const F = T[key], one = x => fmt(x, v, nums);
  let title = fit(fmtAll(F.title, v, nums), TITLE_MAX);
  // a long name: cut it, never the chance words
  if (title.length > TITLE_MAX) { const last = one(F.title[F.title.length - 1]), rest = last.slice(v.N.length); title = v.N.slice(0, Math.max(8, TITLE_MAX - rest.length - 1)).trimEnd() + "…" + rest; }
  if (title.length > TITLE_MAX) title = cut(title, TITLE_MAX);
  return { title, description: fitDesc(fmtAll(F.description, v, nums)), h1: one(F.h1),
    intro: cat === "nodata" ? (T.introNoData ? one(T.introNoData) : "") : one(cat === "party" ? T.introParty : T.intro),
    // round 61: the trade and the net, in a paragraph after the answer
    intro2: cat === "nodata" || cat === "party" || !T.intro2 ? "" : one(T.intro2) };
}
// round 61: what a country's support holds beyond its own aid, in a language (COPY.<l>.country.incl, or inclS for a
// description): its share of EU aid and the cost of hosting refugees, each where the data have it (values euX, refX)
export function countryIncl(l, key, v, nums) {
  const T = C(l, ["country", key]) || {};
  return list3(l, ["eu", "ref"].filter(k => nums[k + "X"]).map(k => fmt(T[k], v, nums)));
}
export function homeText(l, n, dataTo) {
  const T = C(l, ["home"]), v = { n, dataTo }, nums = { nOne: n % 10 === 1 && n % 100 !== 11 };
  return { title: fmt(T.title, v, nums), description: fmt(T.description, v, nums), h1: fmt(T.h1, v, nums), intro: fmt(T.intro, v, nums) };
}
// round 61: the page of support by country in every language (COPY.<l>.static), the other static pages in English
export function staticText(page, v, nums, l = "en") {
  const T = (COPY[l] && COPY[l].static && COPY[l].static[page]) || COPY.en.static[page];
  return { title: fitTitle(fmtAll(T.title, v, nums)), description: fitDesc(fmtAll(T.description, v, nums)), h1: fmt(T.h1, v, nums), intro: fmt(T.intro, v, nums) };
}

